// PV6 comments and mentions, over the real router, index core, policy engine and SQLite D1; notifications-worker
// is faked at its service binding. Fixtures are generated bytes, never real files.

import { randomBytes } from "node:crypto";
import { NOTIFICATIONS_INTERNAL_ACTOR_VALUES } from "@saas/contracts/notifications";
import { FakeDigestStream, World, sha256hex, type User } from "./harness.js";

beforeAll(() => {
  (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream = FakeDigestStream;
});
afterAll(() => {
  delete (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream;
});

describe("comments", () => {
  let w: World;
  let A: { id: string; pub: string };
  let owner: User, editor: User, viewer: User, guest: User, other: User, stranger: User;
  let base: string;
  let libPub: string;

  beforeEach(async () => {
    w = new World();
    A = w.newOrg();
    owner = w.newUser("owner");
    editor = w.newUser("editor");
    viewer = w.newUser("viewer");
    guest = w.newUser("guest");
    other = w.newUser("other");
    stranger = w.newUser("stranger");
    w.grant(A, owner, "owner");
    w.grant(A, editor, "builder");
    w.grant(A, viewer, "viewer");
    const lib = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Brand" })).json.data.library;
    libPub = lib.id;
    base = `/v1/organizations/${A.pub}/libraries/${lib.id}`;
    await w.call(owner, "PUT", `${base}/members/${editor.id}`, { role: "editor" });
    await w.call(owner, "PUT", `${base}/members/${viewer.id}`, { role: "viewer" });
    // Org members' emails live in the platform's users table (guests' are on their membership).
    for (const u of [owner, editor, viewer]) {
      const h = u.id.slice(4);
      const uuid = `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
      w.db.prepare(`INSERT INTO identity_users (id, email, email_lower, display_name, created_at, updated_at) VALUES (?, ?, ?, NULL, ?, ?)`).run(uuid, u.email, u.email, "2026-01-01T00:00:00.000Z", "2026-01-01T00:00:00.000Z");
    }
    for (const g of [guest, other]) {
      await w.call(owner, "POST", `${base}/invitations`, { email: g.email, role: "uploader" });
      await w.call(g, "POST", "/v1/media/invitations/accept");
    }
  });

  async function upload(user: User, name: string) {
    const bytes = randomBytes(100);
    const s = (await w.call(user, "POST", `${base}/uploads`, { name, size: bytes.length, sha256: sha256hex(bytes), mime: "application/octet-stream" })).json.data.session;
    await w.put(user, `${base}/uploads/${s.id}/parts/1`, bytes);
    return (await w.call(user, "POST", `${base}/uploads/${s.id}/commit`)).json.data.file;
  }
  const comments = (user: User, fileId: string) => w.call(user, "GET", `${base}/files/${fileId}/comments`);
  const add = (user: User, fileId: string, body: unknown) => w.call(user, "POST", `${base}/files/${fileId}/comments`, body);

  it("anyone who can read a file comments on it; comments follow the file's access", async () => {
    const f = await upload(editor, "logo.bin");
    const c = await add(viewer, f.id, { body: "Looks great" });
    expect(c.status).toBe(201);
    expect(c.json.data.comment).toMatchObject({ body: "Looks great", author: viewer.id, fileId: f.id, mentions: [] });
    expect(c.json.data.comment.id).toMatch(/^cmt_[0-9a-f]{32}$/);
    await add(editor, f.id, { body: "Thanks!" });
    expect((await comments(viewer, f.id)).json.data.comments.map((x: { body: string }) => x.body)).toEqual(["Looks great", "Thanks!"]);
    // an uploader-only member can't see someone else's file, nor its comments
    expect((await comments(guest, f.id)).status).toBe(404);
    expect((await add(guest, f.id, { body: "hi" })).status).toBe(404);
    expect((await comments(stranger, f.id)).status).toBe(404);
    // on their own file they can
    const mine = await upload(guest, "mine.bin");
    expect((await add(guest, mine.id, { body: "my note" })).status).toBe(201);
    for (const bad of [{ body: "" }, { body: "x".repeat(4001) }, { body: "a\u0000b" }, { body: "ok", mentions: ["bob"] }]) {
      expect([JSON.stringify(bad).slice(0, 40), (await add(viewer, f.id, bad)).status]).toEqual([JSON.stringify(bad).slice(0, 40), 422]);
    }
  });

  it("mentions email members who can read the file, once each; others are dropped without a hint", async () => {
    const f = await upload(editor, "brief.bin");
    const r = await add(editor, f.id, { body: "@viewer @guest @editor please check this before Friday", mentions: [viewer.id, guest.id, editor.id, stranger.id, viewer.id] });
    expect(r.status).toBe(201);
    // viewer can read it; guest (uploader-only) can't; editor is the author; stranger isn't a member
    expect(r.json.data.mentioned).toBe(1);
    expect(r.json.data.comment.mentions).toEqual([viewer.id]);
    expect(w.notifications).toHaveLength(1);
    const n = w.notifications[0]!.body;
    expect(n).toMatchObject({
      orgId: A.id,
      category: "product",
      templateKey: "media.comment_mention",
      recipient: { channel: "email", address: viewer.email, subjectKind: "user", subjectId: viewer.id },
      templateData: { actorName: editor.email, fileName: "brief.bin", libraryName: "Brand", link: `https://app.test/o/${A.pub}/l/${libPub}` },
    });
    expect(n.templateData.excerpt).toContain("please check");
    expect(n.idempotencyKey).toMatch(/^media\.comment_mention:[0-9a-f-]{36}:usr_[0-9a-f]{32}$/);
    // the fake stands in for notifications-worker: the caller name media-worker sends must be one it accepts
    expect(NOTIFICATIONS_INTERNAL_ACTOR_VALUES as readonly string[]).toContain(w.notifications[0]!.headers["x-internal-actor"]);
    // nothing about the file's bytes or links goes in the email
    expect(JSON.stringify(n)).not.toMatch(/serve\.test|sig=|blob\//);
    // a guest is mentionable on their own file
    const own = await upload(guest, "own.bin");
    const r2 = await add(editor, own.id, { body: "@guest thanks", mentions: [guest.id] });
    expect(r2.json.data.mentioned).toBe(1);
  });

  it("authors edit their words; authors and editors resolve and delete; viewers can't touch others' comments", async () => {
    const f = await upload(editor, "x.bin");
    const c = (await add(viewer, f.id, { body: "typo hree" })).json.data.comment;
    const path = `${base}/files/${f.id}/comments/${c.id}`;
    expect((await w.call(editor, "PATCH", path, { body: "edited by someone else" })).status).toBe(404);
    const edited = await w.call(viewer, "PATCH", path, { body: "typo here" });
    expect(edited.json.data.comment).toMatchObject({ body: "typo here" });
    expect(edited.json.data.comment.editedAt).toBeTruthy();
    const resolved = await w.call(editor, "PATCH", path, { resolved: true });
    expect(resolved.json.data.comment).toMatchObject({ resolvedBy: editor.id });
    const other2 = (await add(editor, f.id, { body: "editor's note" })).json.data.comment;
    expect((await w.call(viewer, "DELETE", `${base}/files/${f.id}/comments/${other2.id}`)).status).toBe(404);
    expect((await w.call(editor, "DELETE", path)).status).toBe(200);
    expect((await comments(viewer, f.id)).json.data.comments.map((x: { body: string }) => x.body)).toEqual(["editor's note"]);
    // a comment id from another file is 404
    const g = await upload(editor, "y.bin");
    expect((await w.call(editor, "PATCH", `${base}/files/${g.id}/comments/${other2.id}`, { resolved: true })).status).toBe(404);
  });

  it("a purged file takes its comments with it", async () => {
    const f = await upload(editor, "gone.bin");
    await add(editor, f.id, { body: "bye" });
    await w.call(editor, "DELETE", `${base}/files/${f.id}`);
    expect((await comments(editor, f.id)).status).toBe(404); // trashed: hidden
    await w.call(editor, "DELETE", `${base}/files/${f.id}?permanent=1`);
    const core = [...w.index.cores.values()][0]!;
    const id = f.id.slice(4).replace(/(.{8})(.{4})(.{4})(.{4})(.{12})/, "$1-$2-$3-$4-$5");
    expect(core.listComments(id)).toEqual([]);
  });
});
